import {N,grid,sample,volume} from './engine.js';
export function insidePolygon(p,ps){let inside=false;for(let i=0,j=ps.length-1;i<ps.length;j=i++){let a=ps[i],b=ps[j];if((a[1]>p[1])!==(b[1]>p[1])&&p[0]<(b[0]-a[0])*(p[1]-a[1])/(b[1]-a[1])+a[0])inside=!inside}return inside}
export function nearestPath(p,ps,closed=false){let total=0,lengths=[0],best={distance:Infinity,d:0,side:0,point:null};for(let i=1;i<ps.length;i++){total+=Math.hypot(ps[i][0]-ps[i-1][0],ps[i][1]-ps[i-1][1]);lengths.push(total)}for(let i=0;i<ps.length-(closed?0:1);i++){let a=ps[i],b=ps[(i+1)%ps.length],dx=b[0]-a[0],dy=b[1]-a[1],L=Math.hypot(dx,dy),t=Math.max(0,Math.min(1,((p[0]-a[0])*dx+(p[1]-a[1])*dy)/(L*L||1))),q=[a[0]+t*dx,a[1]+t*dy],dist=Math.hypot(p[0]-q[0],p[1]-q[1]);if(dist<best.distance)best={distance:dist,d:(lengths[i]||0)+t*L,side:L?((p[0]-a[0])*-dy+(p[1]-a[1])*dx)/L:0,point:q}}return{...best,length:total}}
function orient(a,b,c){return(b[0]-a[0])*(c[1]-a[1])-(b[1]-a[1])*(c[0]-a[0])}
export function validateShape(ps,closed,w,h){if(!Array.isArray(ps)||ps.length<(closed?3:2)||ps.length>300||!ps.every(p=>p.length===2&&p.every(Number.isFinite)&&p[0]>=0&&p[0]<=w&&p[1]>=0&&p[1]<=h))throw Error('邊界需在基地內，折線至少 2 點、封閉區至少 3 點，最多 300 點');const count=ps.length-(closed?0:1),eps=Math.max(w,h)*1e-9;for(let i=0;i<count;i++){let a=ps[i],b=ps[(i+1)%ps.length];if(Math.hypot(b[0]-a[0],b[1]-a[1])<eps)throw Error('相鄰節點重合');for(let j=i+1;j<count;j++){if(j===i+1||(closed&&i===0&&j===count-1))continue;let c=ps[j],d=ps[(j+1)%ps.length],o1=orient(a,b,c),o2=orient(a,b,d),o3=orient(c,d,a),o4=orient(c,d,b);const on=(p,a,b)=>Math.abs(orient(a,b,p))<eps&&p[0]>=Math.min(a[0],b[0])-eps&&p[0]<=Math.max(a[0],b[0])+eps&&p[1]>=Math.min(a[1],b[1])-eps&&p[1]<=Math.max(a[1],b[1])+eps;if((o1*o2<0&&o3*o4<0)||on(c,a,b)||on(d,a,b)||on(a,c,d)||on(b,c,d))throw Error('邊界不可自交、相切或重疊，請移開節點')}}if(closed){let area=Math.abs(ps.reduce((s,p,i)=>{let q=ps[(i+1)%ps.length];return s+p[0]*q[1]-p[1]*q[0]},0)/2);if(area<eps)throw Error('封閉區域面積不足')}return true}
export function validateOperation(op,w,h){if(!['platform','path','pit','region'].includes(op.kind))throw Error('未知整坡操作');validateShape(op.points,op.kind!=='path',w,h);for(let key of ['z','endZ','width','cutRatio','fillRatio','cutLimit','fillLimit','grade','crossfall'])if(!Number.isFinite(op[key]))throw Error('整坡參數必須是有限數值');if(Math.abs(op.z)>1e6||Math.abs(op.endZ)>1e6||op.width<=0||op.width>1e5||op.cutRatio<0||op.fillRatio<0||op.cutRatio>100||op.fillRatio>100||op.cutLimit<0||op.fillLimit<0||op.cutLimit>1e5||op.fillLimit>1e5||Math.abs(op.grade)>100||Math.abs(op.crossfall)>100)throw Error('標高、坡比、路寬或影響距離超出範圍');if(!['level','ends','grade','follow'].includes(op.pathMode))throw Error('路徑標高方式無效');return true}
const routeCache=new WeakMap();
export function gradingRoute(op){if(op.kind!=='path'||!op.smooth||op.points.length<3)return op.points;let old=routeCache.get(op);if(old&&old.ref===op.points&&old.length===op.points.length)return old.route;let ps=op.points;for(let k=0;k<2;k++){let next=[ps[0]];for(let i=0;i<ps.length-1;i++){let a=ps[i],b=ps[i+1];next.push([a[0]*.75+b[0]*.25,a[1]*.75+b[1]*.25],[a[0]*.25+b[0]*.75,a[1]*.25+b[1]*.75])}next.push(ps.at(-1));ps=next}routeCache.set(op,{ref:op.points,length:op.points.length,route:ps});return ps}
export function operationSample(op,x,y,input,w,h){const p=[x,y],route=op.kind==='path',near=nearestPath(p,gradingRoute(op),!route);let inFootprint=route?near.distance<=op.width/2:insidePolygon(p,op.points),distance=route?Math.max(0,near.distance-op.width/2):near.distance;let z=op.z;if(route){if(op.pathMode==='ends')z=op.z+(op.endZ-op.z)*near.d/(near.length||1);if(op.pathMode==='grade')z=op.z+near.d*op.grade/100;if(op.pathMode==='follow')z=sample(input,...near.point,w,h)+op.z;z+=Math.max(-op.width/2,Math.min(op.width/2,near.side))*op.crossfall/100}return{inFootprint,distance,z}}
export function applyOperation(input,op,w,h){validateOperation(op,w,h);if(op.enabled===false||op.kind==='region')return input.slice();return grid((x,y)=>{let current=sample(input,x,y,w,h),{inFootprint,distance,z}=operationSample(op,x,y,input,w,h),cut=op.cut!==false,fill=op.fill!==false&&op.kind!=='pit';if(inFootprint)return current>z?(cut?z:current):(fill?z:current);if(current>z&&cut&&distance<=op.cutLimit&&op.cutRatio>0)return Math.min(current,z+distance/op.cutRatio);if(current<z&&fill&&distance<=op.fillLimit&&op.fillRatio>0)return Math.max(current,z-distance/op.fillRatio);return current},w,h)}
export function footprintStats(g,op,w,h){let area=0,surface=0,cell=w*h/N/N;for(let j=0;j<N;j++)for(let i=0;i<N;i++){let x=(i+.5)*w/N,y=(j+.5)*h/N;if(!operationSample(op,x,y,g,w,h).inFootprint)continue;area+=cell;let k=j*(N+1)+i,dx=w/N,dy=h/N;for(let tri of [[k,k+1,k+N+2],[k,k+N+2,k+N+1]]){let [a,b,c]=tri.map(q=>[q%(N+1)*dx,Math.floor(q/(N+1))*dy,g[q]]),u=b.map((v,k)=>v-a[k]),v=c.map((v,k)=>v-a[k]);surface+=Math.hypot(u[1]*v[2]-u[2]*v[1],u[2]*v[0]-u[0]*v[2],u[0]*v[1]-u[1]*v[0])/2}}return{area,surface}}
export function evaluateGrading(source,ops,w,h){let g=source.slice(),stats=[];for(let op of ops){let next=applyOperation(g,op,w,h),v=volume(g,next,w,h),foot=op.enabled===false?{area:0,surface:0}:footprintStats(next,op,w,h);stats.push({...v,...foot});g=next}return{g,stats}}
